def average_precision(ranking, relevant):
    hits, total = 0, 0.0
    for k, doc in enumerate(ranking, start=1):
        if doc in relevant:
            hits += 1
            total += hits / k   # precision at this hit
    return total / len(relevant)

ranking = ["d14","d3","d27","d8","d41",
           "d19","d5","d33","d12","d50"]
relevant = {"d14","d27","d19","d50","d9"}
print(average_precision(ranking, relevant))
